-- Route library seed. Distances and climbs are the commonly quoted figures for
-- each route. Paths are waypoint traces for the map, close but not survey grade.
-- Safe to re-run: existing routes are updated in place by slug.

insert into sg_routes (slug, name, area, region, distance_km, elevation_gain_m, route_type, surface, is_loop, has_shade, has_water_points, has_toilets, shade_note, start_point, nearest_mrt, description, path, sort_order) values
  ('east-coast-park', 'East Coast Park end to end', 'Marine Parade to Bedok', 'east', 10, 6, 'waterfront', 'paved', false, true, true, true, 'Patchy tree cover, the sea breeze does most of the work', 'Car park C, near Marine Cove', 'Marine Parade (TEL) or Bayshore (TEL)', 'The default long run. Pancake flat, separate jogging lane from the cyclists for most of it, and toilets plus drinks kiosks every kilometre or so. Weekend mornings get crowded after 8am.', '[[103.8848,1.2978],[103.895,1.299],[103.905,1.2995],[103.9126,1.301],[103.921,1.303],[103.93,1.3048],[103.938,1.3068],[103.946,1.309],[103.953,1.3105],[103.959,1.3122]]'::jsonb, 1),
  ('marina-bay-loop', 'Marina Bay loop', 'Downtown', 'central', 3.5, 8, 'waterfront', 'paved', true, false, true, true, 'Almost fully exposed. Go before 7:30am or after dark', 'Merlion Park', 'Raffles Place or Bayfront', 'Merlion, Esplanade, Helix Bridge, the MBS promenade and back. Scenic and well lit, so it is the classic after work loop. Expect tourists at the bridges in the evening.', '[[103.8545,1.2868],[103.8553,1.2893],[103.8572,1.2903],[103.86,1.2893],[103.8608,1.2876],[103.86,1.285],[103.859,1.283],[103.8565,1.2818],[103.854,1.282],[103.853,1.284],[103.8545,1.2868]]'::jsonb, 2),
  ('macritchie-treetop', 'MacRitchie TreeTop loop', 'MacRitchie Reservoir', 'central', 10, 120, 'trail', 'trail', true, true, true, true, 'Full canopy for most of the loop, the coolest 10k in the city', 'MacRitchie Reservoir Park, Lornie Road', 'Caldecott or Marymount', 'Rolling dirt trails through the central catchment with a few short sharp climbs. Roots and mud after rain. Water only at the start and the ranger station, so carry a bottle. Mind the monkeys.', '[[103.8333,1.3418],[103.829,1.342],[103.824,1.3445],[103.8195,1.348],[103.815,1.353],[103.814,1.357],[103.8175,1.36],[103.823,1.361],[103.829,1.359],[103.833,1.355],[103.835,1.349],[103.8333,1.3418]]'::jsonb, 3),
  ('southern-ridges', 'Southern Ridges', 'Kent Ridge to Mount Faber', 'central', 5, 140, 'trail', 'mixed', false, true, false, true, 'Shaded forest walk, exposed on Henderson Waves', 'Kent Ridge Park', 'Pasir Panjang or HarbourFront', 'Point to point along the ridgeline: Kent Ridge, HortPark, Alexandra Arch, the Forest Walk, Henderson Waves and up to Mount Faber. Lots of stairs and boardwalk, so it doubles as a hill session.', '[[103.7895,1.2847],[103.7945,1.281],[103.7985,1.279],[103.8015,1.279],[103.807,1.2785],[103.812,1.2768],[103.8155,1.276],[103.819,1.273],[103.8195,1.2712]]'::jsonb, 4),
  ('bishan-amk-park', 'Bishan-Ang Mo Kio Park loop', 'Bishan', 'central', 3, 5, 'park_loop', 'paved', true, true, true, true, 'Decent tree cover along the river', 'Car park B, Bishan side', 'Bishan', 'A flat loop around the naturalised Kallang River. Easy to stack laps for an easy run, and it connects straight into the Kallang PCN if you want more.', '[[103.848,1.3625],[103.844,1.364],[103.8395,1.3648],[103.8355,1.364],[103.834,1.3625],[103.837,1.3612],[103.842,1.3615],[103.846,1.361],[103.848,1.3625]]'::jsonb, 5),
  ('kallang-pcn', 'Kallang Park Connector', 'Bishan to Kallang Riverside', 'central', 11, 12, 'park_connector', 'paved', false, false, true, false, 'Mostly open along the canal, some HDB shade near Toa Payoh', 'Bishan-AMK Park', 'Bishan to Stadium', 'Follows the Kallang River south from Bishan through Toa Payoh and Bendemeer down to the Sports Hub. Good for a one way long run that ends near an MRT. Several road crossings.', '[[103.848,1.3625],[103.854,1.356],[103.86,1.346],[103.864,1.338],[103.865,1.328],[103.868,1.318],[103.87,1.31],[103.871,1.305]]'::jsonb, 6),
  ('kallang-sports-hub', 'Kallang Basin and Sports Hub', 'Kallang', 'central', 5, 4, 'waterfront', 'paved', true, false, true, true, 'Shade only under the stadium roof edge', 'Stadium MRT exit B', 'Stadium', 'Around the National Stadium and along the Kallang Basin waterfront. Wide paths, lit at night and a popular group run spot on weeknights.', '[[103.8745,1.3045],[103.869,1.306],[103.865,1.304],[103.864,1.3005],[103.867,1.2985],[103.872,1.2985],[103.877,1.3],[103.879,1.3025],[103.8745,1.3045]]'::jsonb, 7),
  ('bedok-reservoir', 'Bedok Reservoir loop', 'Bedok North', 'east', 4.3, 10, 'park_loop', 'paved', true, true, true, true, 'Shaded on the north bank, open on the south', 'Bedok Reservoir Park car park A', 'Bedok Reservoir', 'One lap is about 4.3 km with marker posts. Gentle undulation on the north side. A good place for tempo work because nothing interrupts you.', '[[103.93844,1.34152],[103.93764,1.34277],[103.93567,1.34368],[103.93284,1.3441],[103.92958,1.34397],[103.92638,1.34332],[103.92374,1.34224],[103.92204,1.34089],[103.92156,1.33948],[103.92236,1.33823],[103.92433,1.33732],[103.92716,1.3369],[103.93042,1.33703],[103.93362,1.33768],[103.93626,1.33876],[103.93796,1.34011],[103.93844,1.34152]]'::jsonb, 8),
  ('punggol-waterway', 'Punggol Waterway loop', 'Punggol', 'north_east', 5, 4, 'park_loop', 'paved', true, false, true, true, 'Young trees, not much cover yet', 'Punggol Waterway Park, Sentul Crescent', 'Punggol', 'Along both banks of the waterway with bridges to turn at. Breezy and flat, links into the Punggol Promenade if you want to push to Coney Island.', '[[103.898,1.412],[103.902,1.4105],[103.906,1.4085],[103.91,1.406],[103.913,1.404],[103.911,1.4025],[103.907,1.4045],[103.903,1.4068],[103.899,1.4095],[103.898,1.412]]'::jsonb, 9),
  ('pasir-ris-park', 'Pasir Ris Park coastal loop', 'Pasir Ris', 'east', 6, 5, 'waterfront', 'paved', true, true, true, true, 'Mature trees and mangroves, one of the shadier coastal runs', 'Pasir Ris Park car park C', 'Pasir Ris', 'Coastal path plus the mangrove boardwalk side. Quieter than East Coast and noticeably shadier. Watch for kids on bikes on weekends.', '[[103.945,1.38],[103.95,1.382],[103.956,1.383],[103.962,1.3815],[103.958,1.379],[103.952,1.378],[103.945,1.38]]'::jsonb, 10),
  ('jurong-lake-gardens', 'Jurong Lake Gardens loop', 'Jurong East', 'west', 4.5, 6, 'park_loop', 'paved', true, true, true, true, 'Partial shade, better on the Chinese Garden side', 'Lakeside MRT', 'Lakeside or Chinese Garden', 'Circles Jurong Lake through the redeveloped gardens. Flat, smooth and close to two MRT stations, which makes it the main easy run loop in the west.', '[[103.73526,1.33535],[103.73561,1.33749],[103.73494,1.33971],[103.73338,1.34167],[103.73114,1.34307],[103.72858,1.34369],[103.72609,1.34345],[103.72403,1.34239],[103.72274,1.34065],[103.72239,1.33851],[103.72306,1.33629],[103.72462,1.33433],[103.72686,1.33293],[103.72942,1.33231],[103.73191,1.33255],[103.73397,1.33361],[103.73526,1.33535]]'::jsonb, 11),
  ('rail-corridor', 'Rail Corridor (central)', 'Bukit Timah to Hillview', 'west', 4, 20, 'trail', 'trail', false, true, false, false, 'Good canopy for most of the stretch', 'Former Bukit Timah Railway Station', 'King Albert Park or Hillview', 'The old KTM line, now a wide compacted gravel and grass trail. Very gentle grade, soft underfoot, and cooler than the roads either side. Bring your own water.', '[[103.7915,1.339],[103.785,1.344],[103.779,1.351],[103.774,1.358],[103.768,1.363]]'::jsonb, 12),
  ('bukit-timah-summit', 'Bukit Timah Hill summit', 'Bukit Timah Nature Reserve', 'west', 3, 150, 'trail', 'mixed', false, true, true, true, 'Shaded the whole way up', 'Bukit Timah Nature Reserve visitor centre', 'Beauty World', 'Steep paved road to the 163 m summit and back down. Short, but the gradient hits 20 percent in places. Treat it as a hill repeat session, not an easy run.', '[[103.7762,1.3497],[103.7768,1.3512],[103.7758,1.3528],[103.7765,1.3542],[103.7762,1.3546]]'::jsonb, 13),
  ('bishan-stadium-track', 'Bishan Stadium track', 'Bishan', 'central', 0.4, 0, 'track', 'track', true, false, true, true, 'No shade. Track sessions after 6:30pm', 'Bishan ActiveSG Stadium', 'Bishan', 'A standard 400 m public track. Measured laps make it the honest place for intervals and time trials. Check ActiveSG for closures before you go.', '[[103.8514,1.3546],[103.85135,1.35477],[103.85119,1.35492],[103.85095,1.35503],[103.85066,1.35509],[103.85034,1.35509],[103.85005,1.35503],[103.84981,1.35492],[103.84965,1.35477],[103.8496,1.3546],[103.84965,1.35443],[103.84981,1.35428],[103.85005,1.35417],[103.85034,1.35411],[103.85066,1.35411],[103.85095,1.35417],[103.85119,1.35428],[103.85135,1.35443],[103.8514,1.3546]]'::jsonb, 14)
on conflict (slug) do update set
  name = excluded.name,
  area = excluded.area,
  region = excluded.region,
  distance_km = excluded.distance_km,
  elevation_gain_m = excluded.elevation_gain_m,
  route_type = excluded.route_type,
  surface = excluded.surface,
  is_loop = excluded.is_loop,
  has_shade = excluded.has_shade,
  has_water_points = excluded.has_water_points,
  has_toilets = excluded.has_toilets,
  shade_note = excluded.shade_note,
  start_point = excluded.start_point,
  nearest_mrt = excluded.nearest_mrt,
  description = excluded.description,
  path = excluded.path,
  sort_order = excluded.sort_order;
